// Command names here are the JS-visible ones (`invoke("plugin:f1android|speak")`)
// and the identifiers the permission files are generated from — `speak` becomes
// `allow-speak`/`deny-speak` under permissions/autogenerated/. They must stay in
// step with the `#[tauri::command]` fns in src/lib.rs; a mismatch is a runtime
// "command not allowed", not a compile error.
const COMMANDS: &[&str] = &[
    "speak",
    "stop",
    "voices",
    "is_ready",
    "write_document",
    "set_keep_awake",
    "acquire_multicast_lock",
    "release_multicast_lock",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .build();
}
